/** Mount ONCE (root layout) — defines the reusable <symbol>. */
export function BatSymbol() {
  return (
    <svg aria-hidden width="0" height="0" style={{ position: "absolute" }}>
      <defs>
        <symbol id="bat-mark" viewBox="0 0 200 100">
          <path d={BAT_PATH} fill="currentColor" />
        </symbol>
      </defs>
    </svg>
  );
}

export default function BatMark({
  className,
  title = "bat signal",
  decorative = true,
}: {
  className?: string;
  title?: string;
  decorative?: boolean;
}) {
  return (
    <svg
      viewBox="0 0 200 100"
      className={className}
      {...(decorative
        ? { "aria-hidden": true }
        : { role: "img", "aria-label": title })}
    >
      <use href="#bat-mark" />
    </svg>
  );
}
